{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.tagid_final AS WITH logic_enriched AS ( SELECT TO_VARCHAR(LOT_NUMBER) AS LOGIC_LOT_NUMBER, ORIGIN, UNIQUEKEY, ORDER_DATE, EDD, SUPPLIER_ORDER_NO, TRANSFER_BRANCH_CODE, TO_PARTY, FROM_PARTY, PARTY_USER_CODE, BRANCH_SHORT_NAME AS LOGIC_BRANCH_SHORT_NAME, VOUCH_CODE, ORDER_PREFIX, ACTION_CODE, NET_ORDER_AMOUNT, ORDER_AMOUNT, TOTAL_TAX, AGENT_NAME, LOGIC_USER_CODE, PO_MRP, PENDING_QTY, TOTAL_QTY, TXN_CODE AS LOGIC_TXN_CODE, CASE WHEN TRY_TO_NUMBER(PENDING_QTY) = TRY_TO_NUMBER(TOTAL_QTY) THEN \'PENDING FOR GRN\' ELSE \'GRN DONE\' END AS PO_GRN_STATUS FROM snitch_db.maplemonk.logic_purchase_order WHERE ORDER_DATE >= DATEADD(MONTH, -3, CURRENT_DATE) ), tagid_filtered AS ( SELECT TO_VARCHAR(CUSTOMER_PURCHASE_ORDER) AS CUSTOMER_PURCHASE_ORDER, TO_VARCHAR(INDENT_NUMBER) AS INDENT_NUMBER, TO_VARCHAR(LOT_NUMBER) AS LOT_NUMBER, SKU, TRY_TO_NUMBER(RATE) AS RATE, SIZE, CHEST, COLOR, WAIST, INSEAM, SLEEVE, SLOGAN, FC_CODE, TRY_TO_NUMBER(NET_QTY) AS NET_QTY, TRY_TO_DATE(PO_DATE) AS PO_DATE, PRODUCT, COLOR_NO, H_CIRCUM, TRY_TO_DATE(MFG_DATE) AS MFG_DATE, PACKNAME, TXN_CODE, EAN_NUMBER, TRY_TO_NUMBER(PO_TOT_QTY) AS PO_TOT_QTY, SKU_NUMBER, BRANCH_NAME, GROUP_NAME6, VENDOR_CODE, VENDOR_NAME, TRY_TO_DATE(PAYMENT_DATE) AS PAYMENT_DATE, \"AWB/LR Number\" AS AWB_LR_NUMBER, TRY_TO_DATE(APPROVAL_DATE) AS APPROVAL_DATE, CURRENCY_NAME, TRY_TO_DATE(DISPATCH_DATE) AS DISPATCH_DATE, TRY_TO_NUMBER(EXCHANGE_RATE) AS EXCHANGE_RATE, CURRENT_STATUS, PAYMENT_STATUS, TRY_TO_NUMBER(PO_INITIAL_QTY) AS PO_INITIAL_QTY, SHIPPED_STATUS, \"Courier Partner\" AS COURIER_PARTNER, DELIVERY_ADDRESS, PRODUCT_TAG_TYPE, BRANCH_SHORT_NAME, COUNTRY_OF_ORIGIN, TRY_TO_DATE(LAST_UPDATED_DATE) AS LAST_UPDATED_DATE, TRY_TO_NUMBER(PO_UNIT_MRP_PRICE) AS PO_UNIT_MRP_PRICE, TRY_TO_DATE(ORDER_CREATION_DATE) AS ORDER_CREATION_DATE, TRY_TO_NUMBER(PO_EXTRA_PERCENTAGE) AS PO_EXTRA_PERCENTAGE, PRODUCT_DESCRIPTION, TRANSFER_BRANCH_NAME, TRY_TO_DATE(EXPECTED_DELIVERY_DATE) AS EXPECTED_DELIVERY_DATE, TRY_TO_DATE(PRINTING_COMPLETED_DATE) AS PRINTING_COMPLETED_DATE, MANUFACTURED_MARKETED_BY FROM snitch_db.maplemonk.test_get_orders_dump WHERE NOT ( CURRENT_STATUS = \'Not Ordered Yet\' AND ( PO_DATE IS NULL OR TRY_TO_DATE(PO_DATE) < DATEADD(MONTH, -3, CURRENT_DATE) ) ) ) SELECT t.SKU, t.RATE, t.SIZE, t.CHEST, t.COLOR, t.WAIST, t.INSEAM, t.SLEEVE, t.SLOGAN, t.FC_CODE, t.NET_QTY, t.PO_DATE, t.PRODUCT, t.COLOR_NO, t.H_CIRCUM, t.MFG_DATE, t.PACKNAME, t.TXN_CODE, t.EAN_NUMBER, t.LOT_NUMBER, t.PO_TOT_QTY, t.SKU_NUMBER, t.BRANCH_NAME, t.GROUP_NAME6, t.VENDOR_CODE, t.VENDOR_NAME, t.PAYMENT_DATE, t.AWB_LR_NUMBER, t.APPROVAL_DATE, t.CURRENCY_NAME, t.DISPATCH_DATE, t.EXCHANGE_RATE, t.INDENT_NUMBER, t.CURRENT_STATUS, t.PAYMENT_STATUS, t.PO_INITIAL_QTY, t.SHIPPED_STATUS, t.COURIER_PARTNER, t.DELIVERY_ADDRESS, t.PRODUCT_TAG_TYPE, t.BRANCH_SHORT_NAME, t.COUNTRY_OF_ORIGIN, t.LAST_UPDATED_DATE, t.PO_UNIT_MRP_PRICE, t.ORDER_CREATION_DATE, t.PO_EXTRA_PERCENTAGE, t.PRODUCT_DESCRIPTION, t.TRANSFER_BRANCH_NAME, t.EXPECTED_DELIVERY_DATE, t.CUSTOMER_PURCHASE_ORDER, t.PRINTING_COMPLETED_DATE, t.MANUFACTURED_MARKETED_BY, COALESCE(l.LOGIC_LOT_NUMBER, t.LOT_NUMBER, t.CUSTOMER_PURCHASE_ORDER) AS PO_NUMBER, l.PO_GRN_STATUS, l.ORDER_DATE AS LOGIC_ORDER_DATE, l.EDD AS LOGIC_EDD, l.SUPPLIER_ORDER_NO, l.TRANSFER_BRANCH_CODE, l.TO_PARTY, l.FROM_PARTY, l.PARTY_USER_CODE, l.LOGIC_BRANCH_SHORT_NAME, l.VOUCH_CODE, l.ORDER_PREFIX, l.ACTION_CODE, l.NET_ORDER_AMOUNT, l.ORDER_AMOUNT, l.TOTAL_TAX AS LOGIC_TOTAL_TAX, l.AGENT_NAME, l.LOGIC_USER_CODE, l.PO_MRP, l.PENDING_QTY, l.TOTAL_QTY, l.LOGIC_TXN_CODE, l.ORIGIN AS LOGIC_ORIGIN, l.UNIQUEKEY AS LOGIC_UNIQUEKEY FROM tagid_filtered t LEFT JOIN logic_enriched l ON t.LOT_NUMBER = l.LOGIC_LOT_NUMBER ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            